 obj<-list(net=cc@net,netP=cc@netP,LR=cc@LR$LRsig,counts=cnt,contributions=contrib,scope=task$scope,comparison_type=task$comparison,condition=task$condition,network_level=task$network_level,genes=rownames(cc@data.signaling),params=list(version=as.character(packageVersion('CellChat')),type='triMean',population.size=FALSE,raw.use=TRUE,nboot=100,seed=123,min.cells=30,cap=100,epi_equal_within_specimen=state,data_max=max(cc@data.signaling)))
